  id: number;
  title: string;
  tags: string[];
  status: Status;
  createdAt: string;
  due?: string;
  completedAt?: string;
};
type Database = { nextId: number; tasks: Task[] };

const dbPath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  throw new Error(message);
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

function parseId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value) || Number(value) < 1) fail("ID must be a positive integer");
  return Number(value);
}

function readDatabase(): Database {
  const file = Bun.file(dbPath);
  if (!file.size) return { nextId: 1, tasks: [] };
  let data: unknown;
  try {
    data = JSON.parse(readFileSync(dbPath, "utf8"));
  } catch {
    fail("Malformed taskboard database");
  }
  if (!data || typeof data !== "object") fail("Malformed taskboard database");
  const db = data as Partial<Database>;
  if (!Number.isSafeInteger(db.nextId) || (db.nextId as number) < 1 || !Array.isArray(db.tasks)) {
    fail("Malformed taskboard database");
  }
  const ids = new Set<number>();
  let highestId = 0;
  for (const task of db.tasks) {
    if (!task || typeof task !== "object" || !Number.isSafeInteger(task.id) || task.id < 1 ||
      typeof task.title !== "string" || !Array.isArray(task.tags) ||
      (task.status !== "open" && task.status !== "done") || typeof task.createdAt !== "string" ||
      (task.due !== undefined && (!isDate(task.due) || typeof task.due !== "string")) ||
      (task.completedAt !== undefined && typeof task.completedAt !== "string") ||
      task.tags.some(tag => typeof tag !== "string" || tag !== tag.trim().toLowerCase() || !tag) ||
      (task.status === "open" && task.completedAt !== undefined) ||
      (task.status === "done" && task.completedAt === undefined) || ids.has(task.id)) {
      fail("Malformed taskboard database");
    }
    ids.add(task.id);
    highestId = Math.max(highestId, task.id);
  }
  if (db.nextId <= highestId) fail("Malformed taskboard database");
  return db as Database;
}

function writeDatabase(db: Database): void {
  const directory = dbPath.includes("/") ? dbPath.slice(0, dbPath.lastIndexOf("/")) || "." : ".";
  const name = dbPath.slice(dbPath.lastIndexOf("/") + 1);
  const temporary = `${directory}/.${name}.${process.pid}.${Date.now()}.tmp`;
  try {
    writeFileSync(temporary, `${JSON.stringify(db, null, 2)}\n`, "utf8");
    renameSync(temporary, dbPath);
  } catch {
    try { unlinkSync(temporary); } catch { /* best effort */ }
    fail("Could not write taskboard database");
  }
}

function options(args: string[], allowed: string[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (let i = 0; i < args.length; i += 2) {
    const flag = args[i];
    if (!flag?.startsWith("--") || !allowed.includes(flag) || result[flag] !== undefined || args[i + 1] === undefined) {
      fail("Invalid command options");
    }
    result[flag] = args[i + 1];
  }
  return result;
}

function today(): string {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60_000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function main(args: string[]): unknown {
  const command = args.shift();
  if (command === "add") {
    const opt = options(args, ["--title", "--tags", "--due"]);
    const title = opt["--title"]?.trim();
    if (!title) fail("Title must not be empty");
    if (opt["--due"] !== undefined && !isDate(opt["--due"])) fail("Due date must be a valid YYYY-MM-DD date");
    const tags = opt["--tags"] === undefined ? [] : [...new Set(opt["--tags"].split(",").map(x => x.trim().toLowerCase()).filter(Boolean))];
    const db = readDatabase();
    const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString() };
    if (opt["--due"]) task.due = opt["--due"];
    db.tasks.push(task);
    writeDatabase(db);
    return task;
  }
  if (command === "list") {
    const opt = options(args, ["--status", "--tag", "--overdue"]);
    if (opt["--status"] !== undefined && opt["--status"] !== "open" && opt["--status"] !== "done") fail("Status must be open or done");
    if (opt["--overdue"] !== undefined && !isDate(opt["--overdue"])) fail("Overdue date must be a valid YYYY-MM-DD date");
    const tag = opt["--tag"]?.trim().toLowerCase();
    return readDatabase().tasks.filter(task =>
      (!opt["--status"] || task.status === opt["--status"]) &&
      (!tag || task.tags.includes(tag)) &&
      (!opt["--overdue"] || (task.status === "open" && !!task.due && task.due < opt["--overdue"]))
    ).sort((a, b) => a.id - b.id);
  }
  if (command === "done" || command === "delete") {
    if (args.length !== 1) fail(`Usage: ${command} ID`);
    const db = readDatabase();
    const task = db.tasks.find(item => item.id === parseId(args[0]));
